#include <linux/compat.h>
#include <linux/socket.h>
#include <linux/uaccess.h>

long compat_sock_recvmsg_multiple(int fd, struct compat_mmsghdr __user *mmsg,
                                  unsigned int vlen, unsigned int flags,
                                  struct compat_timespec __user *timeout) {
    long ret;
    struct timespec ktimeout = { 0, 0 };
    int copyflags;

    if (timeout) {
        struct compat_timespec ct;
        if (copy_from_user(&ct, timeout, sizeof(ct)))
            return -EFAULT;
        ktimeout.tv_sec = ct.tv_sec;
        ktimeout.tv_nsec = ct.tv_nsec;
    }

    copyflags = (flags & MSG_CMSG_COMPAT) ? 1 : 0;

    ret = kernel_recvmsg_multiple(fd, mmsg, vlen, flags, timeout ? &ktimeout : NULL, copyflags);
    if (ret >= 0 && timeout && !IS_ERR_VALUE(ret)) {
        struct compat_timespec ct;
        ct.tv_sec = ktimeout.tv_sec;
        ct.tv_nsec = ktimeout.tv_nsec;
        if (copy_to_user(timeout, &ct, sizeof(ct)))
            return -EFAULT;
    }

    return ret;
}
